// Tag/card colors — muted, dusty palette.
export const COLORS = {
  coral: '#c17b6a',
  amber: '#c4a06a',
  lime: '#8ba687',
  teal: '#4f8888',
  sky: '#6688a8',
  violet: '#8479a0',
  pink: '#b88a9a',
  slate: '#98a1ac',
}

export const DEFAULT_COLOR = 'sky'

// Matches the dot-matrix background pitch in index.css. Cards snap to the
// midpoints between dots (offset by half a cell) rather than onto the dots
// themselves, so corners land in the gaps of the dot matrix.
export const GRID_SIZE = 22
const GRID_OFFSET = GRID_SIZE / 2

export function snapToGrid(value) {
  return Math.round((value - GRID_OFFSET) / GRID_SIZE) * GRID_SIZE + GRID_OFFSET
}

// All cards share one fixed width, a multiple of GRID_SIZE, so the left and
// right edges both land on grid midpoints.
export const CARD_WIDTH = GRID_SIZE * 10

let uid = 0
export function nextId(prefix) {
  uid += 1
  return `${prefix}${Date.now().toString(36)}${uid}`
}

// The whole app state is this one JSON structure.
export const seedBoard = {
  cards: [
    {
      id: 'c1',
      type: 'note',
      x: 77,
      y: 99,
      w: CARD_WIDTH,
      color: 'amber',
      title: 'Welcome to Kanvy',
      content: 'This whole board is one JSON object. Drag cards around, add new ones, edit text inline.',
    },
    {
      id: 'c2',
      type: 'task',
      x: 363,
      y: 99,
      w: CARD_WIDTH,
      color: 'coral',
      title: 'Design ideas to try',
      content: '',
      tasks: [
        { id: 't1', text: 'pan + zoom canvas', done: false },
        { id: 't2', text: 'connections between cards', done: false },
        { id: 't3', text: 'flat retro card style', done: true },
      ],
    },
    {
      id: 'c3',
      type: 'note',
      x: 671,
      y: 231,
      w: CARD_WIDTH,
      color: 'lime',
      title: 'Colored tags',
      content: 'The dot in the corner is the card’s color tag — a quick visual indicator.',
    },
    {
      id: 'c4',
      type: 'task',
      x: 209,
      y: 363,
      w: CARD_WIDTH,
      color: 'violet',
      title: 'Backlog',
      content: '',
      tasks: [
        { id: 't4', text: 'multi-select', done: false },
        { id: 't5', text: 'card connections', done: false },
      ],
    },
  ],
}

export function newCard(type, { x, y, color = DEFAULT_COLOR } = {}) {
  const base = {
    id: nextId('c'),
    type,
    x: snapToGrid(x ?? 120),
    y: snapToGrid(y ?? 120),
    w: CARD_WIDTH,
    color,
    title: type === 'task' ? 'New list' : 'New note',
    content: '',
  }
  if (type === 'task') {
    base.tasks = []
  }
  return base
}

