:root {
  color-scheme: light;
  --paper: #eef1f4;
  --ink: #1b1e22;
  --line: #1b1e22;
  --surface: #ffffff;
  --shadow: rgba(15, 18, 22, 0.85);
  --dot: rgba(15, 18, 22, 0.08);
  --border-soft: rgba(27, 30, 34, 0.2);
  font-family: 'Fira Code', 'Courier New', monospace;
}

[data-theme='dark'] {
  color-scheme: dark;
  --paper: #1a1d22;
  --ink: #e8ebef;
  --line: #e8ebef;
  --surface: #262a31;
  --shadow: rgba(0, 0, 0, 0.7);
  --dot: rgba(255, 255, 255, 0.08);
  --border-soft: rgba(232, 235, 239, 0.25);
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  background: var(--paper);
  color: var(--ink);
  transition: background-color 0.15s ease, color 0.15s ease;
}

.app {
  height: 100%;
  display: flex;
  flex-direction: column;
}

/* ---------- toolbar ---------- */

.toolbar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  background: var(--paper);
  border-bottom: 3px solid var(--line);
}

.toolbar__brand {
  font-weight: 700;
  font-size: 1.1rem;
  letter-spacing: 0.02em;
  margin-right: 8px;
}

.toolbar__btn {
  font-family: inherit;
  font-size: 0.85rem;
  background: var(--surface);
  color: var(--ink);
  border: 2px solid var(--line);
  padding: 6px 12px;
  cursor: pointer;
  box-shadow: 3px 3px 0 var(--shadow);
}

.toolbar__btn--icon {
  padding: 6px 10px;
  line-height: 1;
}

.toolbar__btn:hover {
  transform: translate(1px, 1px);
  box-shadow: 2px 2px 0 var(--shadow);
}

.toolbar__btn--ghost {
  margin-left: auto;
  background: transparent;
}

.toolbar__colors {
  display: flex;
  gap: 6px;
  padding: 0 6px;
  border-left: 2px solid var(--border-soft);
  border-right: 2px solid var(--border-soft);
  margin: 0 4px;
}

.toolbar__swatch {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 2px solid var(--border-soft);
  cursor: pointer;
  padding: 0;
}

.toolbar__swatch--active {
  outline: 2px solid var(--ink);
  outline-offset: 2px;
}

/* ---------- board ---------- */

.board {
  position: relative;
  flex: 1 1 auto;
  overflow: auto;
  min-height: 0;
  background-image: radial-gradient(var(--dot) 1px, transparent 1px);
  background-size: 22px 22px;
  background-attachment: local;
}

/* ---------- card ---------- */

.card {
  position: absolute;
  background: var(--surface);
  color: var(--ink);
  border: 3px solid var(--line);
  border-radius: 2px;
  box-shadow: 4px 4px 0 var(--shadow);
  padding: 0;
  cursor: grab;
  user-select: none;
}

.card--dragging {
  cursor: grabbing;
  box-shadow: 6px 6px 0 var(--shadow);
  z-index: 10;
}

.card__bar {
  display: flex;
  align-items: center;
