}

.toolbar__btn {
  font-family: inherit;
  font-size: 0.85rem;
  background: var(--surface);
  color: var(--ink);
  border: 2px solid var(--line);
  padding: 6px 12px;
  cursor: pointer;
  box-shadow: 3px 3px 0 var(--shadow);
}

.toolbar__btn--icon {
  padding: 6px 10px;
  line-height: 1;
}

.toolbar__btn:hover {
  transform: translate(1px, 1px);
  box-shadow: 2px 2px 0 var(--shadow);
}

.toolbar__btn--ghost {
  margin-left: auto;
  background: transparent;
}

.toolbar__colors {
  display: flex;
  gap: 6px;
  padding: 0 6px;
  border-left: 2px solid var(--border-soft);
  border-right: 2px solid var(--border-soft);
  margin: 0 4px;
}

.toolbar__swatch {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 2px solid var(--border-soft);
  cursor: pointer;
  padding: 0;
}

.toolbar__swatch--active {
  outline: 2px solid var(--ink);
  outline-offset: 2px;
}

/* ---------- board ---------- */

import { useState } from 'react'
import { COLORS, DEFAULT_COLOR } from '../data/board.js'

export default function Toolbar({ onAddCard, onReset, theme, onToggleTheme }) {
  const [color, setColor] = useState(DEFAULT_COLOR)

  function place() {
    // scatter new cards a bit so they don't stack exactly
    const x = 100 + Math.round(Math.random() * 300)
    const y = 100 + Math.round(Math.random() * 200)
    return { x, y, color }
  }

  return (
    <div className="toolbar">
      <span className="toolbar__brand">kanvy</span>

      <button className="toolbar__btn" onClick={() => onAddCard(place())}>
        + Note
      </button>

      <div className="toolbar__colors">
        {Object.entries(COLORS).map(([name, hex]) => (
          <button
            key={name}
            className={`toolbar__swatch${color === name ? ' toolbar__swatch--active' : ''}`}
            style={{ background: hex }}
            title={name}
            onClick={() => setColor(name)}
          />
        ))}
      </div>

      <button
        className="toolbar__btn toolbar__btn--icon toolbar__btn--ghost"
        onClick={onToggleTheme}
        title={theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'}
      >
        {theme === 'dark' ? '☀️' : '🌙'}
      </button>

      <button className="toolbar__btn" onClick={onReset}>
        Reset board
      </button>
    </div>
  )
}

