import { chromium } from 'playwright'

const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 1000, height: 700 } })
page.on('console', (msg) => console.log('CONSOLE:', msg.type(), msg.text()))
page.on('pageerror', (err) => console.log('PAGEERROR:', err.message))

await page.goto('http://localhost:5173')
await page.waitForSelector('.board')

// clear localStorage to start clean and reload
await page.evaluate(() => localStorage.clear())
await page.reload()
await page.waitForSelector('.card')

await page.screenshot({ path: '/tmp/before-pan.png' })

const boardBox = await page.locator('.board').boundingBox()
const cardBefore = await page.locator('.card').first().boundingBox()
console.log('card before pan (screen coords):', cardBefore)

// right-click drag pan
const startX = boardBox.x + boardBox.width / 2
const startY = boardBox.y + boardBox.height / 2
await page.mouse.move(startX, startY)
await page.mouse.down({ button: 'right' })
await page.mouse.move(startX - 150, startY - 90, { steps: 10 })
await page.mouse.up({ button: 'right' })

await page.screenshot({ path: '/tmp/after-pan.png' })

const cardAfter = await page.locator('.card').first().boundingBox()
console.log('card after pan (screen coords):', cardAfter)
console.log('delta x:', cardAfter.x - cardBefore.x, 'delta y:', cardAfter.y - cardBefore.y)
console.log('expected delta: -150, -90')

// check background-position moved too
const bgPos = await page.locator('.board').evaluate((el) => getComputedStyle(el).backgroundPosition)
console.log('background-position after pan:', bgPos)

// now test dragging a card and snapping
const card = page.locator('.card').nth(1)
const box = await card.boundingBox()
const handleX = box.x + box.width / 2
const handleY = box.y + 5 // grab bar area
await page.mouse.move(handleX, handleY)
await page.mouse.down({ button: 'left' })
await page.mouse.move(handleX + 37, handleY + 13, { steps: 8 }) // arbitrary non-grid delta
await page.mouse.up({ button: 'left' })

const newX = await card.evaluate((el) => el.style.left)
const newY = await card.evaluate((el) => el.style.top)
console.log('card left/top after drag (world coords, should be grid-aligned):', newX, newY)

await page.screenshot({ path: '/tmp/after-card-drag.png' })

await browser.close()

