  const [pan, setPan] = useState({ x: 0, y: 0 })
  const [panning, setPanning] = useState(false)

  function getSiblingRects(excludeId) {
    const rects = []
    cardElsRef.current.forEach((el, id) => {
      if (id === excludeId) return
      rects.push({ x: el.offsetLeft, y: el.offsetTop, width: el.offsetWidth, height: el.offsetHeight })
    })
    return rects
  }

  function handlePointerDown(e) {
    if (e.button !== 2) return
    e.preventDefault()
    panRef.current = { startX: e.clientX, startY: e.clientY, originX: pan.x, originY: pan.y }
    setPanning(true)
    e.currentTarget.setPointerCapture(e.pointerId)
  }

  function handlePointerMove(e) {
    if (!panRef.current) return
    const { startX, startY, originX, originY } = panRef.current
    setPan({ x: originX + (e.clientX - startX), y: originY + (e.clientY - startY) })
  }

  function handlePointerUp(e) {
    if (!panRef.current) return
    panRef.current = null
    setPanning(false)
    try {
      e.currentTarget.releasePointerCapture(e.pointerId)
    } catch {
      // ignore
    }
  }

  return (
    <div
      className={`board${panning ? ' board--panning' : ''}`}
      style={{ '--grid-size': `${GRID_SIZE}px`, backgroundPosition: `${pan.x}px ${pan.y}px` }}
      onContextMenu={(e) => e.preventDefault()}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
    >
      <div className="board__layer" style={{ transform: `translate(${pan.x}px, ${pan.y}px)` }}>
        {board.cards.map((card) => (
          <Card
            key={card.id}
            card={card}
            onMove={actions.moveCard}
            onUpdate={actions.updateCard}
            onRemove={actions.removeCard}
            getSiblingRects={getSiblingRects}
            registerRef={(el) => {
              if (el) cardElsRef.current.set(card.id, el)
              else cardElsRef.current.delete(card.id)
            }}
          />
        ))}
      </div>
    </div>
  )
}

