.toolbar__swatch {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 2px solid var(--border-soft);
  cursor: pointer;
  padding: 0;
}

.toolbar__swatch--active {
  outline: 2px solid var(--ink);
  outline-offset: 2px;
}

/* ---------- board ---------- */

.board {
  position: relative;
  flex: 1 1 auto;
  overflow: hidden;
  min-height: 0;
  background-image: radial-gradient(var(--dot) 1px, transparent 1px);
  background-size: var(--grid-size) var(--grid-size);
}

.board--panning {
  cursor: grabbing;
}

.board__layer {
  position: absolute;
  inset: 0;
}

/* ---------- card ---------- */

.card {
  position: absolute;
  background: var(--surface);
  color: var(--ink);
  border: 3px solid var(--line);
  border-radius: 5px;
  overflow: hidden;
  padding: 0;
  cursor: grab;
  user-select: none;
  transition: background-color 0.1s ease;
}

.card:hover {
  background: var(--surface-hover);
}

.card--dragging {
  cursor: grabbing;
  z-index: 10;
