import { useEffect, useRef, useState } from 'react'
import Card from './Card.jsx'
import { GRID_SIZE } from '../data/board.js'

const MIN_ZOOM = 0.25
const MAX_ZOOM = 2.5
const ZOOM_BUTTON_STEP = 1.2
const WHEEL_ZOOM_INTENSITY = 0.0015

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value))
}

export default function Board({ board, actions }) {
  const boardElRef = useRef(null)
  const panRef = useRef(null)
  const cardElsRef = useRef(new Map())
  const [view, setView] = useState({ x: 0, y: 0, zoom: 1 })
  const [panning, setPanning] = useState(false)

  useEffect(() => {
    const el = boardElRef.current
    if (!el) return

    function onWheel(e) {
      e.preventDefault()
      const rect = el.getBoundingClientRect()
      zoomAt(e.clientX - rect.left, e.clientY - rect.top, Math.exp(-e.deltaY * WHEEL_ZOOM_INTENSITY))
    }

    el.addEventListener('wheel', onWheel, { passive: false })
    return () => el.removeEventListener('wheel', onWheel)
  }, [])

  // Keep (anchorX, anchorY) — in board-viewport pixels — visually fixed while
  // zoom changes by `factor`, so wheel-zoom tracks the cursor and button-zoom
  // tracks the viewport center.
  function zoomAt(anchorX, anchorY, factor) {
    setView((v) => {
      const newZoom = clamp(v.zoom * factor, MIN_ZOOM, MAX_ZOOM)
      if (newZoom === v.zoom) return v
      const worldX = (anchorX - v.x) / v.zoom
      const worldY = (anchorY - v.y) / v.zoom
      return { zoom: newZoom, x: anchorX - worldX * newZoom, y: anchorY - worldY * newZoom }
    })
  }

  function zoomByButton(factor) {
    const rect = boardElRef.current.getBoundingClientRect()
    zoomAt(rect.width / 2, rect.height / 2, factor)
  }

  function resetZoom() {
    const rect = boardElRef.current.getBoundingClientRect()
    zoomAt(rect.width / 2, rect.height / 2, 1 / view.zoom)
  }

  function getSiblingRects(excludeId) {
    const rects = []
    cardElsRef.current.forEach((el, id) => {
      if (id === excludeId) return
      rects.push({ x: el.offsetLeft, y: el.offsetTop, width: el.offsetWidth, height: el.offsetHeight })
    })
    return rects
  }

  function handlePointerDown(e) {
    if (e.button !== 2) return
    e.preventDefault()
    panRef.current = { startX: e.clientX, startY: e.clientY, originX: view.x, originY: view.y }
    setPanning(true)
    e.currentTarget.setPointerCapture(e.pointerId)
  }

  function handlePointerMove(e) {
    if (!panRef.current) return
    const { startX, startY, originX, originY } = panRef.current
    const x = originX + (e.clientX - startX)
    const y = originY + (e.clientY - startY)
    setView((v) => ({ ...v, x, y }))
  }

  function handlePointerUp(e) {
    if (!panRef.current) return
    panRef.current = null
    setPanning(false)
    try {
      e.currentTarget.releasePointerCapture(e.pointerId)
    } catch {
      // ignore
    }
  }

  return (
    <div
      ref={boardElRef}
      className={`board${panning ? ' board--panning' : ''}`}
      style={{
        backgroundPosition: `${view.x}px ${view.y}px`,
        backgroundSize: `${GRID_SIZE * view.zoom}px ${GRID_SIZE * view.zoom}px`,
      }}
      onContextMenu={(e) => e.preventDefault()}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
    >
      <div
        className="board__layer"
        style={{ transform: `translate(${view.x}px, ${view.y}px) scale(${view.zoom})` }}
      >
        {board.cards.map((card) => (
          <Card
            key={card.id}
            card={card}
            zoom={view.zoom}
            onMove={actions.moveCard}
            onUpdate={actions.updateCard}
            onRemove={actions.removeCard}
            getSiblingRects={getSiblingRects}
            registerRef={(el) => {
              if (el) cardElsRef.current.set(card.id, el)
              else cardElsRef.current.delete(card.id)
            }}
          />
        ))}
      </div>

      <div className="board__zoom">
        <button className="board__zoom-btn" onClick={() => zoomByButton(1 / ZOOM_BUTTON_STEP)} title="Zoom out">
          −
        </button>
        <button className="board__zoom-btn board__zoom-btn--reset" onClick={resetZoom} title="Reset zoom">
          {Math.round(view.zoom * 100)}%
        </button>
        <button className="board__zoom-btn" onClick={() => zoomByButton(ZOOM_BUTTON_STEP)} title="Zoom in">
          +
        </button>
      </div>
    </div>
  )
}

import { useState } from 'react'
import { COLORS, DEFAULT_COLOR } from '../data/board.js'

export default function Toolbar({ onAddCard, onReset, theme, onToggleTheme }) {
  const [color, setColor] = useState(DEFAULT_COLOR)

  function place() {
    // scatter new cards a bit so they don't stack exactly
    const x = 100 + Math.round(Math.random() * 300)
    const y = 100 + Math.round(Math.random() * 200)
    return { x, y, color }
  }

  return (
    <div className="toolbar">
      <span className="toolbar__brand">kanvy</span>

      <button className="toolbar__btn" onClick={() => onAddCard(place())}>
        + Note
      </button>

      <div className="toolbar__colors">
        {Object.entries(COLORS).map(([name, hex]) => (
          <button
            key={name}
            className={`toolbar__swatch${color === name ? ' toolbar__swatch--active' : ''}`}
            style={{ background: hex }}
            title={name}
            onClick={() => setColor(name)}
          />
        ))}
      </div>

      <button
        className="toolbar__btn toolbar__btn--icon toolbar__btn--ghost"
        onClick={onToggleTheme}
        title={theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'}
      >
        {theme === 'dark' ? '☀️' : '🌙'}
      </button>

      <button className="toolbar__btn" onClick={onReset}>
        Reset board
      </button>
    </div>
  )
}

import { useCallback, useEffect, useState } from 'react'
import { seedBoard, newCard } from '../data/board.js'

const STORAGE_KEY = 'kanvy.board'

function loadInitialBoard() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (raw) return JSON.parse(raw)
  } catch {
    // ignore corrupt storage, fall back to seed
  }
  return seedBoard
}

export function useBoard() {
  const [board, setBoard] = useState(loadInitialBoard)

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(board))
  }, [board])

  const addCard = useCallback((opts) => {
    setBoard((b) => ({ ...b, cards: [...b.cards, newCard(opts)] }))
  }, [])

  const updateCard = useCallback((id, patch) => {
    setBoard((b) => ({
      ...b,
      cards: b.cards.map((c) => (c.id === id ? { ...c, ...patch } : c)),
    }))
  }, [])

  const moveCard = useCallback((id, x, y) => {
    setBoard((b) => ({
      ...b,
      cards: b.cards.map((c) => (c.id === id ? { ...c, x, y } : c)),
    }))
  }, [])

  const removeCard = useCallback((id) => {
    setBoard((b) => ({ ...b, cards: b.cards.filter((c) => c.id !== id) }))
  }, [])

  const resetBoard = useCallback(() => {
    setBoard(seedBoard)
  }, [])

  return {
    board,
    addCard,
    updateCard,
    moveCard,
    removeCard,
    resetBoard,
  }
}

