import { useEffect, useState } from 'react'
import { useBoard } from './state/useBoard.js'
import { useTheme } from './state/useTheme.js'
import { DEFAULT_COLOR } from './data/board.js'
import Board from './components/Board.jsx'
import Toolbar from './components/Toolbar.jsx'

export default function App() {
  const { board, addCard, duplicateCard, updateCard, moveCard, removeCard, resetBoard } = useBoard()
  const { theme, toggleTheme } = useTheme()
  const [color, setColor] = useState(DEFAULT_COLOR)
  const [selectedId, setSelectedId] = useState(null)

  useEffect(() => {
    function onKeyDown(e) {
      const mod = e.metaKey || e.ctrlKey
      if (!mod) return
      const key = e.key.toLowerCase()

      if (key === 'n') {
        e.preventDefault()
        // scatter new cards a bit so they don't stack exactly
        const x = 100 + Math.round(Math.random() * 300)
        const y = 100 + Math.round(Math.random() * 200)
        setSelectedId(addCard({ x, y, color }))
      } else if (key === 'd') {
        if (!selectedId) return
        e.preventDefault()
        const newId = duplicateCard(selectedId)
        if (newId) setSelectedId(newId)
      }
    }

    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [addCard, duplicateCard, selectedId, color])

  return (
    <div className="app">
      <Toolbar color={color} onColorChange={setColor} onReset={resetBoard} theme={theme} onToggleTheme={toggleTheme} />
      <Board
        board={board}
        selectedId={selectedId}
        onSelectCard={setSelectedId}
        actions={{ updateCard, moveCard, removeCard }}
      />
    </div>
  )
}

