html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  background: var(--paper);
  color: var(--ink);
  transition: background-color 0.15s ease, color 0.15s ease;
}

.app {
  height: 100%;
  display: flex;
  flex-direction: column;
}

/* ---------- toolbar ---------- */

.toolbar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  background: var(--paper);
  border-bottom: 2px solid var(--border-soft);
}

.toolbar__brand {
  font-weight: 700;
  font-size: 1.1rem;
  letter-spacing: 0.02em;
  margin-right: 8px;
}

.toolbar__btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: inherit;
  font-size: 0.85rem;
  background: var(--surface);
  color: var(--ink);
  border: 2px solid var(--line);
  padding: 6px 12px;
  cursor: pointer;
  transition: background-color 0.1s ease;
}

.toolbar__btn--icon {
  padding: 6px 10px;
}

.toolbar__btn:hover {
  background: var(--surface-hover);
}

.toolbar__btn--ghost {
  margin-left: auto;
  background: transparent;
}

.toolbar__colors {
  display: flex;
  gap: 6px;
  padding: 0 6px;
  border-left: 2px solid var(--border-soft);
  border-right: 2px solid var(--border-soft);
  margin: 0 4px;
}

.toolbar__swatch {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 2px solid var(--border-soft);
  cursor: pointer;
  padding: 0;
}

.toolbar__swatch--active {
  outline: 2px solid var(--ink);
  outline-offset: 2px;
}

/* ---------- board ---------- */

.board {
  position: relative;
  flex: 1 1 auto;
  overflow: hidden;
  min-height: 0;
  background-image: radial-gradient(var(--dot) 1px, transparent 1px);
}

.board--panning {
  cursor: grabbing;
}

.board__layer {
  position: absolute;
  inset: 0;
  transform-origin: 0 0;
}

.board__zoom {
  position: absolute;
  right: 14px;
  bottom: 14px;
  display: flex;
  align-items: center;
  gap: 4px;
