}

.card:hover {
  background: var(--surface-hover);
}

.card--dragging {
  cursor: grabbing;
  z-index: 10;
}

.card__bar {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  min-height: 10px;
  padding: 1px 3px;
  background: var(--dot);
  border-bottom: 1px solid var(--border-soft);
}

.card__close {
  flex: 0 0 auto;
  border: none;
  background: transparent;
  font-size: 0.65rem;
  line-height: 1;
  cursor: pointer;
  padding: 0 1px;
  color: var(--ink);
  opacity: 0.35;
}

.card__close:hover {
  opacity: 1;
  color: #d33;
}

.card__content {
  display: block;
  width: 100%;
  min-height: 64px;
  border: none;
  resize: none;
  overflow: hidden;
  font-family: inherit;
  font-size: 0.85rem;
  padding: 8px;
  background: transparent;
  cursor: text;
}

.card__content:focus {
  outline: none;
}

