/* ---------- card ---------- */

.card {
  position: absolute;
  background: var(--surface);
  color: var(--ink);
  border: 3px solid var(--line);
  border-radius: 5px;
  overflow: hidden;
  padding: 0;
  cursor: grab;
  user-select: none;
  transition: background-color 0.1s ease;
}

.card:hover {
  background: var(--surface-hover);
}

.card--selected {
  outline: 2px solid var(--ink);
  outline-offset: 2px;
}

.card-color-menu {
  position: absolute;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px 6px;
  background: var(--surface);
  border: 2px solid var(--line);
  border-radius: 5px;
}

.card--dragging {
  cursor: grabbing;
  z-index: 10;
}

.card__bar {
  display: flex;
  align-items: center;
  justify-content: flex-end;

input.old_string:
.card--selected {
  outline: 2px solid var(--ink);
  outline-offset: 2px;
}

