:root {
  color-scheme: light;
  --paper: #eef1f4;
  --ink: #1b1e22;
  --line: #1b1e22;
  --surface: #ffffff;
  --surface-hover: #f2eee6;
  --dot: rgba(15, 18, 22, 0.08);
  --border-soft: rgba(27, 30, 34, 0.2);
  --outline: rgba(27, 30, 34, 0.45);
  --radius: 5px;
  font-family: 'Fira Code', 'Courier New', monospace;
}

[data-theme='dark'] {
  color-scheme: dark;
  --paper: #1a1d22;
  --ink: #e8ebef;
  --line: #e8ebef;
  --surface: #262a31;
  --surface-hover: #2f343c;
  --dot: rgba(255, 255, 255, 0.08);
  --border-soft: rgba(232, 235, 239, 0.25);
  --outline: rgba(232, 235, 239, 0.35);
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  background: var(--paper);
  color: var(--ink);
  transition: background-color 0.15s ease, color 0.15s ease;
}

.app {
  height: 100%;
  display: flex;
  flex-direction: column;
}

/* ---------- toolbar ---------- */

.toolbar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  background: var(--paper);
  border-bottom: 2px solid var(--border-soft);
}

.toolbar__brand {
  font-weight: 700;
  font-size: 1.1rem;
  letter-spacing: 0.02em;
  margin-right: 8px;
}

.toolbar__btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: inherit;
  font-size: 0.85rem;
  background: var(--surface);
  color: var(--ink);
  border: 2px solid var(--border-soft);
  border-radius: var(--radius);
  padding: 6px 12px;
  cursor: pointer;
  transition: background-color 0.1s ease;
}

.toolbar__btn--icon {
  padding: 6px 10px;
}

.toolbar__btn:hover {
  background: var(--surface-hover);
}

.toolbar__btn--ghost {
  margin-left: auto;
  background: transparent;
}

.swatch {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 2px solid var(--border-soft);
  cursor: pointer;
  padding: 0;
}

.swatch--active {
  outline: 2px solid var(--outline);
  outline-offset: 2px;
}

/* ---------- board ---------- */

.board {
  position: relative;
  flex: 1 1 auto;
  overflow: hidden;
  min-height: 0;
  background-image: radial-gradient(var(--dot) 1px, transparent 1px);
}

.board--panning {
  cursor: grabbing;
}

.board__layer {
  position: absolute;
  inset: 0;
  transform-origin: 0 0;
}

.board__zoom {
  position: absolute;
  right: 14px;
  bottom: 14px;
  display: flex;
  align-items: center;
  gap: 4px;
}

.board__zoom-btn {
  font-family: inherit;
  font-size: 0.9rem;
  background: var(--surface);
  color: var(--ink);
  border: 2px solid var(--border-soft);
  width: 28px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius);
  cursor: pointer;
}

.board__zoom-btn:hover {
  background: var(--surface-hover);
}

.board__zoom-btn--reset {
  width: auto;
  padding: 0 8px;
  font-size: 0.75rem;
}

/* ---------- card ---------- */

.card {
  position: absolute;
  background: var(--surface);
  color: var(--ink);
  border: 3px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  padding: 0;
  cursor: grab;
  user-select: none;
  transition: background-color 0.1s ease;
}

.card:hover {
  background: var(--surface-hover);
}

.card--selected {
  outline: 2px solid var(--outline);
  outline-offset: 2px;
  z-index: 5;
}

.card-color-menu {
  position: absolute;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px 6px;
  background: var(--surface);
  border: 2px solid var(--outline);
  border-radius: var(--radius);
  z-index: 20;
}

.card--dragging {
  cursor: grabbing;
  z-index: 10;
}

.card__bar {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  min-height: 10px;
  padding: 1px 3px;
  background: var(--dot);
  border-bottom: 1px solid var(--border-soft);
}

.card__content {
  display: block;
  width: 100%;
  min-height: 64px;
  border: none;
  resize: none;
  overflow: hidden;
  font-family: inherit;
  font-size: 0.85rem;
  padding: 8px;
  background: transparent;
  cursor: text;
}

.card__content:focus {
  outline: none;
}

